import re

def equation_mistake(sentence):
    """Replace the '=' sign with another operator."""
    return re.sub(r'\=', random.choice(['>', '<', '==', '<=', '>=']), sentence)

def inequality_mistake(sentence):
    """Replace the operator with another operator."""
    return re.sub(r'[><=]', random.choice(['>', '<', '==', '<=', '>='']), sentence)

def proportion_mistake(sentence):
    """Replace the ratio with another ratio."""
    return re.sub(r'\:(\s?\d+\s?)', f':{random.randint(1, 100)}', sentence)

def calculation_mistake(sentence):
    """Replace an operator or a number with another one."""
    parts = sentence.split()
    for i, part in enumerate(parts):
        if part in ['+', '-', '*', '/']:
            parts[i] = random.choice(['+', '-', '*', '/'])
        elif part.isdigit():
            parts[i] = str(random.randint(1, 100))
    return ' '.join(parts)

def reference_mistake(sentence):
    """Replace the previous calculation with another one."""
    parts = sentence.split()
    for i, part in enumerate(parts):
        if part.isalpha():
            parts[i] = f'{random.randint(1, 100)}'
    return ' '.join(parts)

def generate_mistaken_sentence(sentence, type):
    if type == 'equation':
        return equation_mistake(sentence)
    elif type == 'inequality':
        return inequality_mistake(sentence)
    elif type == 'proportion':
        return proportion_mistake(sentence)
    elif type == 'calculation':
        return calculation_mistake(sentence)
    elif type == 'reference':
        return reference_mistake(sentence)
    else:
        return "Invalid type"

